package cn.binbin.crm;
import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;import java.net.*;import java.util.*;
class P3ProtocolTest {
 @Test void mixedReadAllDoesNotWidenOwnWrite(){var sales=SaasService.parameters("role_code","SALES","record_scope","OWN_SHARED","ticket_can_read",true,"ticket_can_write",true);var viewer=SaasService.parameters("role_code","VIEWER","record_scope","ALL","ticket_can_read",true);var a=P3Access.from(List.of(sales,viewer));assertTrue(a.tickets().readAll());assertFalse(a.tickets().writeAll());assertTrue(a.tickets().write());assertFalse(a.slaManage());}
 @Test void integrationNeedsAdminAndPublisherNeedsManager(){var a=P3Access.from(List.of(SaasService.parameters("role_code","SALES","record_scope","ALL","knowledge_can_read",true,"knowledge_can_write",true,"knowledge_can_publish",true,"integration_can_read",true,"integration_can_manage",true)));assertFalse(a.knowledgePublish());assertFalse(a.integrationManage());assertEquals(P3Access.none(),P3Access.defaults(Set.of()));}
 @Test void vaultIsBoundToTenantAndSubscription(){var vault=new IntegrationCrypto("1a".repeat(32));UUID tenant=UUID.randomUUID(),hook=UUID.randomUUID();String secret=Crypto.token(),sealed=vault.encrypt(tenant,hook,secret);assertFalse(sealed.contains(secret));assertEquals(secret,vault.decrypt(tenant,hook,sealed));assertThrows(IllegalStateException.class,()->vault.decrypt(UUID.randomUUID(),hook,sealed));assertThrows(IllegalStateException.class,()->vault.decrypt(tenant,UUID.randomUUID(),sealed));}
 @Test void canonicalSignatureBindsBodyPathNonceAndMethod(){String secret="test",base=IntegrationCrypto.inbound("POST","/api/v1/inbound/leads","1792000000","a".repeat(16),"{\"name\":\"客户\"}");String signature=IntegrationCrypto.hmac(secret,base);assertTrue(IntegrationCrypto.equal(signature,signature));assertFalse(IntegrationCrypto.equal(signature,IntegrationCrypto.hmac(secret,base+" ")));assertFalse(IntegrationCrypto.equal(signature,signature.toUpperCase()));assertFalse(IntegrationCrypto.equal(signature,null));}
 @Test void reservedAddressesAndIpv6TunnelsAreRejected()throws Exception{for(String host:List.of("127.0.0.1","0.0.0.0","10.1.2.3","169.254.169.254","172.16.0.1","192.168.0.1","100.100.100.200","198.18.0.1","192.0.2.1","::1","fe80::1","fc00::1","2001:db8::1","2002:a00:1::1"))assertFalse(WebhookTransport.publicAddress(InetAddress.getByName(host)),host);assertTrue(WebhookTransport.publicAddress(InetAddress.getByName("8.8.8.8")));assertTrue(WebhookTransport.publicAddress(InetAddress.getByName("2606:4700:4700::1111")));}
 @Test void privateMockRequiresEveryIsolationGuard(){var prod=new WebhookTransport(false,"jdbc:postgresql://native/crm_acceptance","p3-acceptance-1");String mock="http://crm-p0-verification.railway.internal:2526/hook";assertThrows(ApiError.class,()->prod.uri(mock));assertNotNull(new WebhookTransport(true,"jdbc:postgresql://native/crm_acceptance","p3-acceptance-1").uri(mock));assertThrows(ApiError.class,()->prod.uri("https://user:pass@example.com/hook"));assertThrows(ApiError.class,()->prod.uri("https://example.com:8080/hook"));assertThrows(ApiError.class,()->prod.uri("https://example.com/hook#secret"));}
 @Test void retryIsBoundedAndTemplatesOnlyHaveKnownVariables(){assertEquals(15,IntegrationService.retrySeconds(1));assertEquals(1920,IntegrationService.retrySeconds(8));assertEquals(3600,IntegrationService.retrySeconds(10));assertThrows(ApiError.class,()->CampaignService.template("{{email}}"));assertEquals("客户 / 企业",CampaignService.expand("{{name}} / {{company}}",Map.of("name","客户","company","企业")));}
}
